import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        String filePath = "<tmp>";

        List<String> lines = new ArrayList<>();
        BufferedReader br = new BufferedReader(new FileReader(filePath));
        String line;
        while ((line = br.readLine()) != null) {
            lines.add(line);
        }
        br.close();

        Map<String, List<Double>> deptSalaries = new TreeMap<>();
        Map<String, Integer> deptCount = new TreeMap<>();
        String highestName = "";
        double highestSalary = -1;
        double totalBudget = 0;

        for (int i = 1; i < lines.size(); i++) {
            String[] parts = lines.get(i).split(",");
            if (parts.length < 6) continue;
            String name = parts[1].trim();
            String department = parts[2].trim();
            String salaryStr = parts[3].trim().replace("$", "").replace(",", "");
            double salary = Double.parseDouble(salaryStr);

            deptSalaries.computeIfAbsent(department, k -> new ArrayList<>()).add(salary);
            deptCount.put(department, deptCount.getOrDefault(department, 0) + 1);

            if (salary > highestSalary) {
                highestSalary = salary;
                highestName = name;
            }

            totalBudget += salary;
        }

        StringBuilder sb = new StringBuilder();
        sb.append("=== Salary Report ===\n");
        sb.append("\n");
        sb.append("Average Salary by Department:\n");

        for (Map.Entry<String, List<Double>> entry : deptSalaries.entrySet()) {
            List<Double> salaries = entry.getValue();
            double sum = 0;
            for (double s : salaries) sum += s;
            double avg = sum / salaries.size();
            sb.append(String.format("  %s: $%,.2f\n", entry.getKey(), avg));
        }

        sb.append("\n");
        sb.append(String.format("Highest Paid: %s ($%,.0f)\n", highestName, highestSalary));
        sb.append("\n");
        sb.append("Departments with >2 employees:\n");

        for (Map.Entry<String, Integer> entry : deptCount.entrySet()) {
            if (entry.getValue() > 2) {
                sb.append(String.format("  %s (%d employees)\n", entry.getKey(), entry.getValue()));
            }
        }

        sb.append("\n");
        sb.append(String.format("Total Budget: $%,.0f\n", totalBudget));

        System.out.print(sb.toString());
    }
}

