import * as fs from 'fs';

const logFile = '<tmp>';
const content = fs.readFileSync(logFile, 'utf-8');
const lines = content.split('\n').filter(line => line.trim() !== '');

const levelCounts: Map<string, number> = new Map();
const componentErrors: Map<string, number> = new Map();
const errorMessages: Set<string> = new Set();
const hourCounts: Map<string, number> = new Map();

const regex = /^\[(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})\] (\w+) \(([^)]+)\) - (.+)$/;

for (const line of lines) {
    const match = line.match(regex);
    if (!match) continue;

    const [, timestamp, level, component, message] = match;

    levelCounts.set(level, (levelCounts.get(level) || 0) + 1);

    if (level === 'ERROR') {
        componentErrors.set(component, (componentErrors.get(component) || 0) + 1);
        errorMessages.add(message);
    }

    const hour = timestamp.substring(11, 13);
    hourCounts.set(hour, (hourCounts.get(hour) || 0) + 1);
}

const out: string[] = [];
out.push('=== Log Analysis ===');
out.push('');
out.push('Entries by Level:');
const sortedLevels = [...levelCounts.entries()].sort((a, b) => a[0].localeCompare(b[0]));
for (const [level, count] of sortedLevels) {
    out.push(`  ${level}: ${count}`);
}
out.push('');

let maxComponent = '';
let maxErrors = 0;
for (const [comp, count] of componentErrors) {
    if (count > maxErrors || (count === maxErrors && comp < maxComponent)) {
        maxErrors = count;
        maxComponent = comp;
    }
}
out.push(`Component with Most Errors: ${maxComponent} (${maxErrors} errors)`);
out.push('');

out.push('Unique Error Messages:');
const sortedMessages = [...errorMessages].sort((a, b) => a.localeCompare(b));
for (const msg of sortedMessages) {
    out.push(`  - ${msg}`);
}
out.push('');

let busiestHour = '';
let busiestCount = 0;
for (const [hour, count] of hourCounts) {
    if (count > busiestCount || (count === busiestCount && hour < busiestHour)) {
        busiestCount = count;
        busiestHour = hour;
    }
}
out.push(`Busiest Hour: ${busiestHour}:00 (${busiestCount} entries)`);

process.stdout.write(out.join('\n') + '\n');

