import java.io.*;
import java.util.*;
import java.util.regex.*;

public class Main {
    public static void main(String[] args) throws Exception {
        String filePath = "<tmp>";

        List<String> lines;
        try (BufferedReader br = new BufferedReader(new FileReader(filePath))) {
            lines = new ArrayList<>();
            String line;
            while ((line = br.readLine()) != null) {
                lines.add(line);
            }
        }

        Pattern pattern = Pattern.compile("\\[(\\d{4}-\\d{2}-\\d{2} \\d{2}:\\d{2}:\\d{2})\\]\\s+(\\S+)\\s+\\(([^)]+)\\)\\s+-\\s+(.*)");

        Map<String, Integer> levelCounts = new TreeMap<>();
        Map<String, Integer> errorByComponent = new HashMap<>();
        Set<String> errorMessages = new TreeSet<>();
        Map<Integer, Integer> hourCounts = new HashMap<>();

        for (String line : lines) {
            Matcher m = pattern.matcher(line.trim());
            if (m.matches()) {
                String timestamp = m.group(1);
                String level = m.group(2);
                String component = m.group(3);
                String message = m.group(4);

                levelCounts.put(level, levelCounts.getOrDefault(level, 0) + 1);

                int hour = Integer.parseInt(timestamp.substring(11, 13));
                hourCounts.put(hour, hourCounts.getOrDefault(hour, 0) + 1);

                if (level.equals("ERROR")) {
                    errorByComponent.put(component, errorByComponent.getOrDefault(component, 0) + 1);
                    errorMessages.add(message);
                }
            }
        }

        String topComponent = "";
        int topErrors = 0;
        for (Map.Entry<String, Integer> e : errorByComponent.entrySet()) {
            if (e.getValue() > topErrors || (e.getValue() == topErrors && e.getKey().compareTo(topComponent) < 0)) {
                topErrors = e.getValue();
                topComponent = e.getKey();
            }
        }

        int busiestHour = 0;
        int busiestCount = 0;
        for (Map.Entry<Integer, Integer> e : hourCounts.entrySet()) {
            if (e.getValue() > busiestCount || (e.getValue() == busiestCount && e.getKey() < busiestHour)) {
                busiestCount = e.getValue();
                busiestHour = e.getKey();
            }
        }

        StringBuilder sb = new StringBuilder();
        sb.append("=== Log Analysis ===\n");
        sb.append("\n");
        sb.append("Entries by Level:\n");
        for (Map.Entry<String, Integer> e : levelCounts.entrySet()) {
            sb.append("  ").append(e.getKey()).append(": ").append(e.getValue()).append("\n");
        }
        sb.append("\n");
        sb.append("Component with Most Errors: ").append(topComponent).append(" (").append(topErrors).append(" errors)\n");
        sb.append("\n");
        sb.append("Unique Error Messages:\n");
        for (String msg : errorMessages) {
            sb.append("  - ").append(msg).append("\n");
        }
        sb.append("\n");
        sb.append("Busiest Hour: ").append(String.format("%02d:00", busiestHour)).append(" (").append(busiestCount).append(" entries)\n");

        System.out.print(sb.toString());
    }
}

