import Foundation

let filePath = "<tmp>"

let content = try! String(contentsOfFile: filePath, encoding: .utf8)
let lines = content.components(separatedBy: "\n").filter { !$0.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty }

let dataLines = lines.dropFirst()

struct Employee {
    let name: String
    let department: String
    let salary: Double
}

var employees: [Employee] = []

for line in dataLines {
    let parts = line.components(separatedBy: ",")
    if parts.count >= 6 {
        let name = parts[1].trimmingCharacters(in: .whitespaces)
        let department = parts[2].trimmingCharacters(in: .whitespaces)
        let salary = Double(parts[3].trimmingCharacters(in: .whitespaces)) ?? 0
        employees.append(Employee(name: name, department: department, salary: salary))
    }
}

func formatInt(_ value: Int) -> String {
    let formatter = NumberFormatter()
    formatter.numberStyle = .decimal
    formatter.locale = Locale(identifier: "en_US")
    formatter.maximumFractionDigits = 0
    formatter.minimumFractionDigits = 0
    return formatter.string(from: NSNumber(value: value)) ?? "\(value)"
}

func formatDecimal(_ value: Double) -> String {
    let formatter = NumberFormatter()
    formatter.numberStyle = .decimal
    formatter.locale = Locale(identifier: "en_US")
    formatter.maximumFractionDigits = 2
    formatter.minimumFractionDigits = 2
    return formatter.string(from: NSNumber(value: value)) ?? String(format: "%.2f", value)
}

