use std::collections::BTreeMap;
use std::fs;

fn add_commas(s: &str) -> String {
    let (int_part, dec_part) = if let Some(pos) = s.find('.') {
        (&s[..pos], &s[pos..])
    } else {
        (s, "")
    };
    let int_chars: Vec<char> = int_part.chars().collect();
    let mut result = String::new();
    let len = int_chars.len();
    for (i, c) in int_chars.iter().enumerate() {
        if i > 0 && (len - i) % 3 == 0 {
            result.push(',');
        }
        result.push(*c);
    }
    result.push_str(dec_part);
    result
}

fn main() {
    let path = "<tmp>";
    let content = fs::read_to_string(path).expect("Failed to read file");
    let lines: Vec<&str> = content.lines().collect();

    let header: Vec<&str> = lines[0].split(',').map(|s| s.trim()).collect();
    let name_idx = header.iter().position(|c| c == "name").unwrap();
    let dept_idx = header.iter().position(|c| c == "department").unwrap();
    let salary_idx = header.iter().position(|c| c == "salary").unwrap();

    let mut employees: Vec<(String, String, f64)> = Vec::new();

    for line in &lines[1..] {
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }
        let fields: Vec<&str> = trimmed.split(',').collect();
        let name = fields[name_idx].trim().to_string();
        let dept = fields[dept_idx].trim().to_string();
        let salary: f64 = fields[salary_idx].trim().parse().unwrap();
        employees.push((name, dept, salary));
    }

    let mut dept_salaries: BTreeMap<String, Vec<f64>> = BTreeMap::new();
    for (name, dept, salary) in &employees {
        dept_salaries.entry(dept.clone()).or_insert_with(Vec::new).push(*salary);
    }

    let highest = employees.iter().max_by(|a, b| a.2.partial_cmp(&b.2).unwrap()).unwrap();
    let total: f64 = employees.iter().map(|e| e.2).sum();

    println!("=== Salary Report ===");
    println!();
    println!("Average Salary by Department:");
    for (dept, salaries) in &dept_salaries {
        let avg: f64 = salaries.iter().sum::<f64>() / salaries.len() as f64;
        let avg_str = format!("{:.2}", avg);
        println!("  {}: ${}", dept, add_commas(&avg_str));
    }
    println!();
    let highest_int = highest.2 as i64;
    println!("Highest Paid: {} (${})", highest.0, add_commas(&highest_int.to_string()));
    println!();
    println!("Departments with >2 employees:");
    for (dept, salaries) in &dept_salaries {
        if salaries.len() > 2 {
            println!("  {} ({} employees)", dept, salaries.len());
        }
    }
    println!();
    let total_int = total as i64;
    println!("Total Budget: ${}", add_commas(&total_int.to_string()));
}

