    public static void main(String[] args) throws Exception {
        String path = "<tmp>";

        StringBuilder sb = new StringBuilder();
        try (BufferedReader br = new BufferedReader(new FileReader(path))) {
            int ch;
            while ((ch = br.read()) != -1) {
                sb.append((char) ch);
            }
        }
        String json = sb.toString();

        List<String> nodes = new ArrayList<>();
        int nodesKey = json.indexOf("\"nodes\"");
        int bracketStart = json.indexOf('[', nodesKey);
        int bracketEnd = findMatchingBracket(json, bracketStart);
        String nodesStr = json.substring(bracketStart + 1, bracketEnd);
        int i = 0;
        while (i < nodesStr.length()) {
            if (nodesStr.charAt(i) == '"') {
                int end = nodesStr.indexOf('"', i + 1);
                nodes.add(nodesStr.substring(i + 1, end));
                i = end + 1;
            } else {
                i++;
            }
        }

        Map<String, Integer> nodeIndex = new HashMap<>();
        for (int idx = 0; idx < nodes.size(); idx++) {
            nodeIndex.put(nodes.get(idx), idx);
        }

        int edgesKey = json.indexOf("\"edges\"");
        int edgesArrStart = json.indexOf('[', edgesKey);
        int edgesArrEnd = findMatchingBracket(json, edgesArrStart);
        String edgesStr = json.substring(edgesArrStart + 1, edgesArrEnd);

