        int k = 0;
        while (k < edgesStr.length()) {
            if (edgesStr.charAt(k) == '{') {
                int objEnd = edgesStr.indexOf('}', k);
                String obj = edgesStr.substring(k, objEnd + 1);
                String from = extractString(obj, "from");
                String to = extractString(obj, "to");
                int weight = extractInt(obj, "weight");
                int fi = nodeIndex.get(from);
                int ti = nodeIndex.get(to);
                edges.add(new int[]{weight, fi, ti});
                k = objEnd + 1;
            } else {
                k++;
            }
