use std::fs;
use std::collections::BTreeMap;

fn main() {
    let path = "<tmp>";
    let content = fs::read_to_string(path).expect("Failed to read file");

    let mut level_counts: BTreeMap<String, usize> = BTreeMap::new();
    let mut error_component_counts: BTreeMap<String, usize> = BTreeMap::new();
    let mut error_messages: Vec<String> = Vec::new();
    let mut hour_counts: [usize; 24] = [0; 24];

    for line in content.lines() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }

        let close_bracket = line.find(']').unwrap();
        let timestamp = &line[1..close_bracket];

        let hour: usize = timestamp[11..13].parse().unwrap_or(0);
        hour_counts[hour] += 1;

        let rest = &line[close_bracket + 2..];

        let space_pos = rest.find(' ').unwrap();
        let level = &rest[..space_pos];

        *level_counts.entry(level.to_string()).or_insert(0) += 1;

        let after_level = &rest[space_pos + 1..];

        let open_paren = after_level.find('(').unwrap();
        let close_paren = after_level.find(')').unwrap();
        let component = &after_level[open_paren + 1..close_paren];

        let after_paren = &after_level[close_paren + 1..];
        let message = after_paren.trim_start_matches(" - ").to_string();

        if level == "ERROR" {
            *error_component_counts.entry(component.to_string()).or_insert(0) += 1;
            error_messages.push(message);
        }
    }

    error_messages.sort();
    error_messages.dedup();

    let (top_component, top_count) = error_component_counts
        .iter()
        .max_by_key(|(_, c)| c)
        .map(|(k, v)| (k.clone(), *v))
        .unwrap_or_else(|| ("NONE".to_string(), 0));

    let (busiest_hour, busiest_count) = (0..24)
        .enumerate()
        .max_by_key(|(_, c)| *c)
        .unwrap_or((0, 0));

    println!("=== Log Analysis ===");
    println!();
    println!("Entries by Level:");
    for (level, count) in &level_counts {
        println!("  {}: {}", level, count);
    }
    println!();
    println!("Component with Most Errors: {} ({} errors)", top_component, top_count);
    println!();
    println!("Unique Error Messages:");
    for msg in &error_messages {
        println!("  - {}", msg);
    }
    println!();
    println!("Busiest Hour: {:02}:00 ({} entries)", busiest_hour, busiest_count);
}

