} DeptInfo;

static void format_money_2dp(char *buf, size_t bufsz, double val) {
    char tmp[128];
    snprintf(tmp, sizeof(tmp), "%.2f", val);
    int dp = -1;
    for (int i = 0; tmp[i]; i++) {
        if (tmp[i] == '.') { dp = i; break; }
    }
    if (dp == -1) dp = (int)strlen(tmp);
    int intlen = dp;
    int pos = 0;
    for (int i = 0; i < intlen; i++) {
        if (i > 0 && (intlen - i) % 3 == 0) {
            if ((size_t)pos + 1 < bufsz) buf[pos++] = ',';
        }
        if ((size_t)pos + 1 < bufsz) buf[pos++] = tmp[i];
    }
    for (int i = dp; tmp[i] && (size_t)pos + 1 < bufsz; i++) {
        buf[pos++] = tmp[i];
    }
    buf[pos] = '\0';
}

static void format_int_commas(char *buf, size_t bufsz, long long val) {
    char tmp[128];
    snprintf(tmp, sizeof(tmp), "%lld", val);
    int len = (int)strlen(tmp);
    int pos = 0;
    for (int i = 0; i < len; i++) {
        if (i > 0 && (len - i) % 3 == 0) {
            if ((size_t)pos + 1 < bufsz) buf[pos++] = ',';
        }
        if ((size_t)pos + 1 < bufsz) buf[pos++] = tmp[i];
    }
    buf[pos] = '\0';
}

int main(void) {
    const char *filepath = "<tmp>";

    FILE *f = fopen(filepath, "r");
    if (!f) {
        fprintf(stderr, "Cannot open file\n");
        return 1;
    }

    /* Skip header line */
    char *hline = NULL;
    size_t hcap = 0;
    if (getline(&hline, &hcap, f) == -1) {
        free(hline);
        fclose(f);
        return 1;
    }
    free(hline);
    hline = NULL;

    /* Read employees */
    int emp_cap = 0, emp_count = 0;
    Employee *employees = NULL;

    while (1) {
        char *line = NULL;
        size_t lcap = 0;
        ssize_t len = getline(&line, &lcap, f);
        if (len == -1) break;

        if (len > 0 && line[len - 1] == '\n') line[len - 1] = '\0';
        if (len > 0 && line[len - 1] == '\r') line[len - 1] = '\0';
        if (len <= 0 || line[0] == '\0') { free(line); continue; }

        char *fields[64];
        int nf = 0;
        char *p = line;
        while (nf < 64) {
            fields[nf++] = p;
            char *c = strchr(p, ',');
            if (!c) break;
            *c = '\0';
            p = c + 1;
        }

        if (nf >= 4) {
            if (emp_count == emp_cap) {
                emp_cap = emp_cap ? emp_cap * 2 : 64;
                Employee *tmp = realloc(employees, (size_t)emp_cap * sizeof(Employee));
                if (!tmp) { free(line); fclose(f); return 1; }
                employees = tmp;
            }
            employees[emp_count].name = strdup(fields[1]);
            employees[emp_count].department = strdup(fields[2]);
            employees[emp_count].salary = atof(fields[3]);
            emp_count++;
        }
        free(line);
    }
    fclose(f);

    if (emp_count == 0) {
        printf("=== Salary Report ===\n\n");
        printf("Average Salary by Department:\n\n");
        printf("Highest Paid: N/A\n\n");
        printf("Departments with >2 employees:\n\n");
        printf("Total Budget: $0\n");
        return 0;
    }

    /* Build department info */
    int dcap = 0, dcount = 0;
    DeptInfo *depts = NULL;

    for (int i = 0; i < emp_count; i++) {
        int found = 0;
        for (int j = 0; j < dcount; j++) {
            if (strcmp(depts[j].name, employees[i].department) == 0) {
                depts[j].total += employees[i].salary;
                depts[j].count++;
                found = 1;
                break;
            }
        }
        if (!found) {
            if (dcount == dcap) {
                dcap = dcap ? dcap * 2 : 32;
                DeptInfo *tmp = realloc(depts, (size_t)dcap * sizeof(DeptInfo));
                if (!tmp) return 1;
                depts = tmp;
            }
            depts[dcount].name = employees[i].department;
            depts[dcount].total = employees[i].salary;
            depts[dcount].count = 1;
            dcount++;
        }
    }

    /* Sort departments alphabetically (simple selection sort) */
    for (int i = 0; i < dcount - 1; i++) {
        int min = i;
        for (int j = i + 1; j < dcount; j++) {
            if (strcmp(depts[j].name, depts[min].name) < 0) min = j;
        }
        if (min != i) {
            DeptInfo t = depts[i];
            depts[i] = depts[min];
            depts[min] = t;
        }
    }

    /* Find highest paid */
    int hi = 0;
    for (int i = 1; i < emp_count; i++) {
        if (employees[i].salary > employees[hi].salary) hi = i;
    }

    /* Total budget */
    double total_budget = 0.0;
    for (int i = 0; i < emp_count; i++) total_budget += employees[i].salary;

    /* Output */
    printf("=== Salary Report ===\n");
    printf("\n");
    printf("Average Salary by Department:\n");
    for (int i = 0; i < dcount; i++) {
        char buf[256];
        double avg = depts[i].total / (double)depts[i].count;
