    JSON_ARRAY,
    JSON_OBJECT
} json_type;

typedef struct json_value json_value;

typedef struct {
    char *key;
    json_value *value;
} json_member;

struct json_value {
    json_type type;
    union {
        int boolean;
        double number;
        char *string;
        struct {
            json_value **items;
            int count;
            int cap;
        } array;
        struct {
            json_member *members;
            int count;
            int cap;
        } object;
    } u;
};

static json_value *json_new(void) {
    json_value *v = (json_value *)calloc(1, sizeof(json_value));
    if (!v) { fprintf(stderr, "OOM\n"); exit(1); }
    v->type = JSON_NULL;
    return v;
}

static void json_free(json_value *v) {
