    if (!buf) { fprintf(stderr, "OOM\n"); exit(1); }
    int len = 0;

    while (p->pos < p->len) {
        char c = p->s[p->pos];
        if (c == '"') {
            p->pos++;
            buf[len] = '\0';
            return buf;
        }
        if (c == '\\') {
