            if (p->pos >= p->len) { free(buf); return NULL; }
            char e = p->s[p->pos];
            switch (e) {
                case '"':  if (len + 1 >= cap) { cap *= 2; buf = realloc(buf, cap); } buf[len++] = '"'; p->pos++; break;
                case '\\': if (len + 1 >= cap) { cap *= 2; buf = realloc(buf, cap); } buf[len++] = '\\'; p->pos++; break;
                case '/':  if (len + 1 >= cap) { cap *= 2; buf = realloc(buf, cap); } buf[len++] = '/'; p->pos++; break;
                case 'b':  if (len + 1 >= cap) { cap *= 2; buf = realloc(buf, cap); } buf[len++] = '\b'; p->pos++; break;
                case 'f':  if (len + 1 >= cap) { cap *= 2; buf = realloc(buf, cap); } buf[len++] = '\f'; p->pos++; break;
                case 'n':  if (len + 1 >= cap) { cap *= 2; buf = realloc(buf, cap); } buf[len++] = '\n'; p->pos++; break;
                case 'r':  if (len + 1 >= cap) { cap *= 2; buf = realloc(buf, cap); } buf[len++] = '\r'; p->pos++; break;
                case 't':  if (len + 1 >= cap) { cap *= 2; buf = realloc(buf, cap); } buf[len++] = '\t'; p->pos++; break;
                case 'u': {
