        p->pos++;
        return obj;
    }
    while (1) {
        skip_ws(p);
        char *key = parse_string_raw(p);
        if (!key) { json_free(obj); return NULL; }
        skip_ws(p);
        if (p->pos >= p->len || p->s[p->pos] != ':') { free(key); json_free(obj); return NULL; }
        p->pos++; /* skip : */
        skip_ws(p);
        json_value *val = parse_value(p);
        if (!val) { free(key); json_free(obj); return NULL; }
        object_set(obj, key, val);
        skip_ws(p);
        if (p->pos < p->len && p->s[p->pos] == ',') {
            p->pos++;
        } else if (p->pos < p->len && p->s[p->pos] == '}') {
            p->pos++;
            break;
        } else {
            json_free(obj);
            return NULL;
        }
    }
    return obj;
}

static json_value *parse_value(parser *p) {
    skip_ws(p);
    if (p->pos >= p->len) return NULL;
    char c = p->s[p->pos];
    if (c == 'n') {
        if (p->pos + 4 <= p->len && strncmp(p->s + p->pos, "null", 4) == 0) {
            p->pos += 4;
            json_value *v = json_new();
            v->type = JSON_NULL;
            return v;
        }
        return NULL;
    }
    if (c == 't') {
        if (p->pos + 4 <= p->len && strncmp(p->s + p->pos, "true", 4) == 0) {
            p->pos += 4;
            json_value *v = json_new();
            v->type = JSON_BOOL;
            v->u.boolean = 1;
            return v;
        }
        return NULL;
    }
    if (c == 'f') {
        if (p->pos + 5 <= p->len && strncmp(p->s + p->pos, "false", 5) == 0) {
            p->pos += 5;
            json_value *v = json_new();
            v->type = JSON_BOOL;
            v->u.boolean = 0;
            return v;
        }
        return NULL;
    }
    if (c == '"') {
        char *s = parse_string_raw(p);
        if (!s) return NULL;
        json_value *v = json_new();
        v->type = JSON_STRING;
        v->u.string = s;
        return v;
    }
    if (c == '[') return parse_array(p);
    if (c == '{') return parse_object(p);
    /* number */
    {
        int start = p->pos;
        if (c == '-') p->pos++;
        while (p->pos < p->len && (isdigit((unsigned char)p->s[p->pos]) || p->s[p->pos] == '.' ||
               p->s[p->pos] == 'e' || p->s[p->pos] == 'E' || p->s[p->pos] == '+' || p->s[p->pos] == '-'))
            p->pos++;
        int len = p->pos - start;
        char *numstr = (char *)malloc(len + 1);
        if (!numstr) { fprintf(stderr, "OOM\n"); exit(1); }
        memcpy(numstr, p->s + start, len);
        numstr[len] = '\0';
        double d = strtod(numstr, NULL);
        free(numstr);
        json_value *v = json_new();
        v->type = JSON_NUMBER;
        v->u.number = d;
        return v;
    }
}

static json_value *parse_json(const char *text, int len) {
    parser p;
    p.s = text;
    p.pos = 0;
    p.len = len;
    return parse_value(&p);
}

/* Deep equality for array dedup */
static int json_equal(const json_value *a, const json_value *b) {
    if (a->type != b->type) return 0;
    switch (a->type) {
        case JSON_NULL: return 1;
        case JSON_BOOL: return a->u.boolean == b->u.boolean;
        case JSON_NUMBER: return a->u.number == b->u.number;
        case JSON_STRING: return strcmp(a->u.string, b->u.string) == 0;
        case JSON_ARRAY:
            if (a->u.array.count != b->u.array.count) return 0;
            for (int i = 0; i < a->u.array.count; i++)
                if (!json_equal(a->u.array.items[i], b->u.array.items[i])) return 0;
            return 1;
        case JSON_OBJECT:
            if (a->u.object.count != b->u.object.count) return 0;
            for (int i = 0; i < a->u.object.count; i++) {
                int found = 0;
                for (int j = 0; j < b->u.object.count; j++) {
                    if (strcmp(a->u.object.members[i].key, b->u.object.members[j].key) == 0) {
                        if (json_equal(a->u.object.members[i].value, b->u.object.members[j].value)) {
                            found = 1;
                        }
                        break;
                    }
                }
                if (!found) return 0;
            }
            return 1;
    }
    return 0;
}

static int array_contains(const json_value *arr, const json_value *item) {
    for (int i = 0; i < arr->u.array.count; i++)
        if (json_equal(arr->u.array.items[i], item)) return 1;
    return 0;
}

/* Deep merge */
static json_value *deep_merge(const json_value *a, const json_value *b) {
    /* Both objects */
    if (a->type == JSON_OBJECT && b->type == JSON_OBJECT) {
        json_value *result = json_new();
        result->type = JSON_OBJECT;
        /* Copy all from A */
        for (int i = 0; i < a->u.object.count; i++) {
            char *key = strdup(a->u.object.members[i].key);
            if (!key) { fprintf(stderr, "OOM\n"); exit(1); }
            /* We need a deep copy of A's value */
            json_value *acopy = deep_merge(a->u.object.members[i].value, a->u.object.members[i].value);
            object_set(result, key, acopy);
        }
        /* Merge B into result */
        for (int i = 0; i < b->u.object.count; i++) {
            const char *bkey = b->u.object.members[i].key;
            /* Check if key exists in result */
            int found = -1;
            for (int j = 0; j < result->u.object.count; j++) {
                if (strcmp(result->u.object.members[j].key, bkey) == 0) {
                    found = j;
                    break;
                }
            }
            if (found >= 0) {
                json_value *merged = deep_merge(result->u.object.members[found].value, b->u.object.members[i].value);
                json_free(result->u.object.members[found].value);
                result->u.object.members[found].value = merged;
            } else {
                char *key = strdup(bkey);
                if (!key) { fprintf(stderr, "OOM\n"); exit(1); }
                json_value *bcopy = deep_merge(b->u.object.members[i].value, b->u.object.members[i].value);
                object_set(result, key, bcopy);
            }
        }
        return result;
    }

    /* Both arrays: concatenate, remove duplicates */
    if (a->type == JSON_ARRAY && b->type == JSON_ARRAY) {
        json_value *result = json_new();
        result->type = JSON_ARRAY;
        /* Add items from A (dedup within A) */
        for (int i = 0; i < a->u.array.count; i++) {
            if (!array_contains(result, a->u.array.items[i])) {
                json_value *copy = deep_merge(a->u.array.items[i], a->u.array.items[i]);
                array_push(result, copy);
            }
        }
        /* Add items from B that are not already in result */
        for (int i = 0; i < b->u.array.count; i++) {
            if (!array_contains(result, b->u.array.items[i])) {
                json_value *copy = deep_merge(b->u.array.items[i], b->u.array.items[i]);
                array_push(result, copy);
            }
        }
        return result;
    }

    /* Scalar conflict or type mismatch: B overrides A */
    if (b->type == JSON_OBJECT) {
        json_value *result = json_new();
        result->type = JSON_OBJECT;
        for (int i = 0; i < b->u.object.count; i++) {
            char *key = strdup(b->u.object.members[i].key);
            if (!key) { fprintf(stderr, "OOM\n"); exit(1); }
            json_value *copy = deep_merge(b->u.object.members[i].value, b->u.object.members[i].value);
            object_set(result, key, copy);
        }
        return result;
    }
    if (b->type == JSON_ARRAY) {
        json_value *result = json_new();
        result->type = JSON_ARRAY;
        for (int i = 0; i < b->u.array.count; i++) {
            if (!array_contains(result, b->u.array.items[i])) {
                json_value *copy = deep_merge(b->u.array.items[i], b->u.array.items[i]);
                array_push(result, copy);
            }
        }
        return result;
    }
    /* Scalar B */
    {
        json_value *result = json_new();
        result->type = b->type;
        switch (b->type) {
            case JSON_NULL: break;
            case JSON_BOOL: result->u.boolean = b->u.boolean; break;
            case JSON_NUMBER: result->u.number = b->u.number; break;
            case JSON_STRING: result->u.string = strdup(b->u.string); break;
            default: break;
        }
        return result;
    }
}

/* Sort object members alphabetically */
static int member_cmp(const void *a, const void *b) {
    const json_member *ma = (const json_member *)a;
    const json_member *mb = (const json_member *)b;
    return strcmp(ma->key, mb->key);
}

static void sort_object(json_value *obj) {
    if (obj->type != JSON_OBJECT) return;
    qsort(obj->u.object.members, obj->u.object.count, sizeof(json_member), member_cmp);
    for (int i = 0; i < obj->u.object.count; i++)
        sort_object(obj->u.object.members[i].value);
}

/* Pretty print */
static void print_string_escaped(FILE *f, const char *s) {
    fputc('"', f);
    for (const char *p = s; *p; p++) {
        unsigned char c = (unsigned char)*p;
        switch (c) {
            case '"':  fputs("\\\"", f); break;
            case '\\': fputs("\\\\", f); break;
            case '\b': fputs("\\b", f); break;
            case '\f': fputs("\\f", f); break;
            case '\n': fputs("\\n", f); break;
            case '\r': fputs("\\r", f); break;
            case '\t': fputs("\\t", f); break;
            default:
                if (c < 0x20) {
                    fprintf(f, "\\u%04x", c);
                } else {
                    fputc(c, f);
                }
        }
    }
    fputc('"', f);
}

static void print_number(FILE *f, double d) {
    if (isnan(d) || isinf(d)) {
        fputs("null", f);
        return;
    }
    if (d == (double)(long long)d && fabs(d) < 9.223372036854775808e18) {
        fprintf(f, "%lld", (long long)d);
    } else {
        char buf[64];
        snprintf(buf, sizeof(buf), "%.15g", d);
        /* Ensure it looks like a number (has . or e) */
        int has_dot = 0, has_e = 0;
        for (char *p = buf; *p; p++) {
            if (*p == '.') has_dot = 1;
            if (*p == 'e' || *p == 'E') has_e = 1;
        }
        if (!has_dot && !has_e) {
            strcat(buf, ".0");
        }
        fputs(buf, f);
    }
}

static void print_value(FILE *f, const json_value *v, int indent) {
    switch (v->type) {
        case JSON_NULL:
            fputs("null", f);
            break;
        case JSON_BOOL:
            fputs(v->u.boolean ? "true" : "false", f);
            break;
        case JSON_NUMBER:
            print_number(f, v->u.number);
            break;
        case JSON_STRING:
            print_string_escaped(f, v->u.string);
            break;
        case JSON_ARRAY:
            if (v->u.array.count == 0) {
                fputs("[]", f);
            } else {
                fputs("[\n", f);
                for (int i = 0; i < v->u.array.count; i++) {
                    for (int j = 0; j < (indent + 1) * 2; j++) fputc(' ', f);
                    print_value(f, v->u.array.items[i], indent + 1);
                    if (i < v->u.array.count - 1) fputc(',', f);
                    fputc('\n', f);
                }
                for (int j = 0; j < indent * 2; j++) fputc(' ', f);
                fputs("]", f);
            }
            break;
        case JSON_OBJECT:
            if (v->u.object.count == 0) {
                fputs("{}", f);
            } else {
                fputs("{\n", f);
                for (int i = 0; i < v->u.object.count; i++) {
                    for (int j = 0; j < (indent + 1) * 2; j++) fputc(' ', f);
                    print_string_escaped(f, v->u.object.members[i].key);
                    fputs(": ", f);
                    print_value(f, v->u.object.members[i].value, indent + 1);
                    if (i < v->u.object.count - 1) fputc(',', f);
                    fputc('\n', f);
                }
                for (int j = 0; j < indent * 2; j++) fputc(' ', f);
                fputs("}", f);
            }
            break;
    }
}

static char *read_file(const char *path, int *out_len) {
    FILE *f = fopen(path, "rb");
    if (!f) {
        fprintf(stderr, "Cannot open %s\n", path);
        exit(1);
    }
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = (char *)malloc(sz + 1);
    if (!buf) { fprintf(stderr, "OOM\n"); exit(1); }
    size_t rd = fread(buf, 1, sz, f);
    buf[rd] = '\0';
    fclose(f);
    *out_len = (int)rd;
    return buf;
}

int main(void) {
    int len_a, len_b;
    char *text_a = read_file("<tmp>", &len_a);
    char *text_b = read_file("<tmp>", &len_b);

    json_value *a = parse_json(text_a, len_a);
    json_value *b = parse_json(text_b, len_b);
    if (!a || !b) {
        fprintf(stderr, "JSON parse error\n");
        return 1;
    }

    json_value *merged = deep_merge(a, b);
    sort_object(merged);

    print_value(stdout, merged, 0);
    fputc('\n', stdout);

    json_free(a);
    json_free(b);
    json_free(merged);
    free(text_a);
    free(text_b);
    return 0;
}
