import * as path from 'path';

const rootDir = '<tmp>';

interface FileInfo {
  relativePath: string;
  lines: number;
  chars: number;
}

function countLines(buffer: Buffer): number {
  if (buffer.length === 0) return 0;
  let count = 0;
  for (let i = 0; i < buffer.length; i++) {
    if (buffer[i] === 10) count++;
  }
  if (buffer[buffer.length - 1] !== 10) count++;
  return count;
}

function walkDir(dir: string, root: string, visited: Set<string>): FileInfo[] {
  const results: FileInfo[] = [];
  let entries: fs.Dirent[];
  try {
    entries = fs.readdirSync(dir, { withFileTypes: true });
  } catch {
    return results;
  }

  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);

    if (entry.isSymbolicLink()) {
      continue;
    }

    if (entry.isDirectory()) {
      let realPath: string;
      try {
        realPath = fs.realpathSync(fullPath);
      } catch {
        continue;
      }
      if (visited.has(realPath)) continue;
      visited.add(realPath);
      const sub = walkDir(fullPath, root, visited);
      for (const f of sub) results.push(f);
    } else if (entry.isFile()) {
      const buffer = fs.readFileSync(fullPath);
      const relativePath = path.relative(root, fullPath).split(path.sep).join('/');
      results.push({
        relativePath,
        lines: countLines(buffer),
        chars: buffer.length
      });
    }
  }

  return results;
}

const visited = new Set<string>();
try {
  const realRoot = fs.realpathSync(rootDir);
  visited.add(realRoot);
} catch {
  // If we can't resolve, just proceed
}

