use std::io::{Read, Write};
use std::net::TcpStream;

enum Json {
    Null,
    Bool(bool),
    Number(f64),
    String(String),
    Array(Vec<Json>),
    Object(Vec<(String, Json)>),
}

struct Parser {
    data: Vec<char>,
    pos: usize,
}

impl Parser {
    fn new(s: &str) -> Self {
        Parser { data: s.chars().collect(), pos: 0 }
    }

    fn peek(&self) -> Option<char> {
        self.data.get(self.pos).copied()
    }

    fn next(&mut self) -> Option<char> {
        let c = self.data.get(self.pos).copied();
        if c.is_some() {
            self.pos += 1;
        }
        c
    }

    fn skip_whitespace(&mut self) {
        while let Some(c) = self.peek() {
            if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
                self.pos += 1;
            } else {
                break;
            }
        }
    }

    fn parse(&mut self) -> Json {
        self.skip_whitespace();
        match self.peek() {
            Some('{') => self.parse_object(),
            Some('[') => self.parse_array(),
            Some('"') => Json::String(self.parse_string()),
            Some('t') => { self.pos += 4; Json::Bool(true) }
            Some('f') => { self.pos += 5; Json::Bool(false) }
            Some('n') => { self.pos += 4; Json::Null }
            _ => {
                let start = self.pos;
                while let Some(c) = self.peek() {
                    if c == ',' || c == '}' || c == ']' || c == ' ' || c == '\t' || c == '\n' || c == '\r' {
                        break;
                    }
                    self.pos += 1;
                }
                let s: String = self.data[start..self.pos].iter().collect();
                if let Ok(n) = s.parse::<f64>() {
                    Json::Number(n)
                } else {
                    Json::Null
                }
            }
        }
    }

    fn parse_object(&mut self) -> Json {
        self.next();
        let mut obj = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some('}') {
            self.next();
            return Json::Object(obj);
        }
        loop {
            self.skip_whitespace();
            let key = self.parse_string();
            self.skip_whitespace();
            self.next();
            let val = self.parse();
            obj.push((key, val));
            self.skip_whitespace();
            match self.next() {
                Some(',') => continue,
                Some('}') => break,
                _ => break,
            }
        }
        Json::Object(obj)
    }

    fn parse_array(&mut self) -> Json {
        self.next();
        let mut arr = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some(']') {
            self.next();
            return Json::Array(arr);
        }
        loop {
            let val = self.parse();
            arr.push(val);
            self.skip_whitespace();
            match self.next() {
                Some(',') => continue,
                Some(']') => break,
                _ => break,
            }
        }
        Json::Array(arr)
    }

    fn parse_string(&mut self) -> String {
        self.next();
        let mut s = String::new();
        loop {
            match self.next() {
                Some('"') => break,
                Some('\\') => {
                    match self.next() {
                        Some('"') => s.push('"'),
                        Some('\\') => s.push('\\'),
                        Some('/') => s.push('/'),
                        Some('n') => s.push('\n'),
                        Some('t') => s.push('\t'),
                        Some('r') => s.push('\r'),
                        Some('b') => s.push('\u{0008}'),
                        Some('f') => s.push('\u{000C}'),
                        Some('u') => {
                            let mut code: u32 = 0;
                            for _ in 0..4 {
                                if let Some(c) = self.next() {
                                    code = code * 16 + c.to_digit(16).unwrap_or(0);
                                }
                            }
                            if let Some(ch) = char::from_u32(code) {
                                s.push(ch);
                            }
                        }
                        _ => {}
                    }
                }
                Some(c) => s.push(c),
                None => break,
            }
        }
        s
    }
}

fn get_string(obj: &[(String, Json)], key: &str) -> String {
    for (k, v) in obj {
        if k == key {
            if let Json::String(s) = v {
                return s.clone();
            }
        }
    }
    String::new()
}

fn get_number(obj: &[(String, Json)], key: &str) -> f64 {
    for (k, v) in obj {
        if k == key {
            if let Json::Number(n) = v {
                return *n;
            }
        }
    }
    0.0
}

fn decode_chunked(body: &str) -> String {
    let mut decoded = String::new();
    let mut remaining = body;
    loop {
        let line_end = match remaining.find("\r\n") {
            Some(idx) => idx,
            None => break,
        };
        let size_str = remaining[..line_end].trim();
        let size = match usize::from_str_radix(size_str, 16) {
            Ok(s) => s,
            Err(_) => break,
        };
        if size == 0 {
            break;
        }
        let data_start = line_end + 2;
        let data_end = data_start + size;
        if data_end > remaining.len() {
            break;
        }
        decoded.push_str(&remaining[data_start..data_end]);
        if data_end + 2 <= remaining.len() {
            remaining = &remaining[data_end + 2..];
        } else {
            remaining = &remaining[data_end..];
        }
    }
    decoded
}

