use std::collections::BTreeMap;
use std::fs;

#[derive(Debug, Clone)]
enum Json {
    Null,
    Bool(bool),
    Num(f64),
    Str(String),
    Arr(Vec<Json>),
    Obj(BTreeMap<String, Json>),
}

impl Json {
    fn deep_eq(&self, other: &Json) -> bool {
        match (self, other) {
            (Json::Null, Json::Null) => true,
            (Json::Bool(a), Json::Bool(b)) => a == b,
            (Json::Num(a), Json::Num(b)) => a == b,
            (Json::Str(a), Json::Str(b)) => a == b,
            (Json::Arr(a), Json::Arr(b)) => {
                a.len() == b.len() && a.iter().zip(b.iter()).all(|(x, y)| x.deep_eq(y))
            }
            (Json::Obj(a), Json::Obj(b)) => {
                a.len() == b.len()
                    && a.iter()
                        .all(|(k, v)| b.get(k).map_or(false, |bv| v.deep_eq(bv)))
            }
            _ => false,
        }
    }
}

struct Parser {
    data: Vec<char>,
    pos: usize,
}

impl Parser {
    fn new(s: &str) -> Self {
        Parser { data: s.chars().collect(), pos: 0 }
    }

    fn skip_ws(&mut self) {
        while self.pos < self.data.len() {
            match self.data[self.pos] {
                ' ' | '\t' | '\n' | '\r' => self.pos += 1,
                _ => break,
            }
        }
    }

    fn peek(&self) -> Option<char> {
        self.data.get(self.pos).copied()
    }

    fn advance(&mut self) -> char {
        let c = self.data[self.pos];
        self.pos += 1;
        c
    }

    fn parse(&mut self) -> Json {
        self.skip_ws();
        let v = self.parse_value();
        self.skip_ws();
        v
    }

    fn parse_value(&mut self) -> Json {
        self.skip_ws();
        match self.peek() {
            Some('{') => self.parse_object(),
            Some('[') => self.parse_array(),
            Some('"') => Json::Str(self.parse_string()),
            Some('t') => { self.expect("true"); Json::Bool(true) }
            Some('f') => { self.expect("false"); Json::Bool(false) }
            Some('n') => { self.expect("null"); Json::Null }
            Some(_) => self.parse_number(),
            None => panic!("Unexpected end of input"),
        }
    }

    fn expect(&mut self, s: &str) {
        for c in s.chars() {
            if self.pos >= self.data.len() || self.data[self.pos] != c {
                panic!("Parse error at position {}", self.pos);
            }
            self.pos += 1;
        }
    }

    fn parse_object(&mut self) -> Json {
        self.advance(); // {
        let mut map = BTreeMap::new();
        self.skip_ws();
        if self.peek() == Some('}') {
            self.advance();
            return Json::Obj(map);
        }
        loop {
            self.skip_ws();
            let key = self.parse_string();
            self.skip_ws();
            if self.peek() != Some(':') {
                panic!("Expected ':' at position {}", self.pos);
