#include <sys/stat.h>
#include <sys/types.h>
#include <errno.h>

#define BASE_DIR "<tmp>"

typedef struct {
    char *relpath;
    long lines;
    long chars;
    char *ext;
} FileEntry;

typedef struct {
    FileEntry *entries;
    int count;
    int capacity;
} FileList;

static void file_list_init(FileList *fl) {
    fl->entries = NULL;
    fl->count = 0;
    fl->capacity = 0;
}

static void file_list_add(FileList *fl, const char *relpath, long lines, long chars, const char *ext) {
    if (fl->count >= fl->capacity) {
        fl->capacity = fl->capacity ? fl->capacity * 2 : 64;
        FileEntry *tmp = realloc(fl->entries, (size_t)fl->capacity * sizeof(FileEntry));
        if (!tmp) { perror("realloc"); exit(1); }
        fl->entries = tmp;
    }
    FileEntry *e = &fl->entries[fl->count++];
    e->relpath = strdup(relpath);
    if (!e->relpath) { perror("strdup"); exit(1); }
    e->lines = lines;
    e->chars = chars;
    e->ext = strdup(ext);
    if (!e->ext) { perror("strdup"); exit(1); }
}

static const char *get_extension(const char *filename) {
    size_t len = strlen(filename);
    if (len == 0) return "";
    size_t i = len;
    while (i > 1) {
        i--;
        if (filename[i] == '.') return &filename[i];
    }
    return "";
}

static void count_file(const char *fullpath, long *lines, long *chars) {
    *lines = 0;
    *chars = 0;

    struct stat st;
    if (stat(fullpath, &st) == 0) {
        *chars = (long)st.st_size;
    }

    FILE *f = fopen(fullpath, "rb");
    if (!f) return;

    int c;
    int last_char = -1;
    while ((c = fgetc(f)) != EOF) {
        if (c == '\n') (*lines)++;
        last_char = c;
    }
    if (last_char != -1 && last_char != '\n') (*lines)++;

    fclose(f);
}

static void walk_dir(const char *dirpath, const char *relprefix, FileList *fl) {
