int main(void) {
    const char *path = "<tmp>";

    FILE *f = fopen(path, "r");
    if (!f) { fprintf(stderr, "Cannot open file\n"); return 1; }
    fseek(f, 0, SEEK_END);
    long fsize = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *json = malloc((size_t)fsize + 1);
    if (!json) { fclose(f); return 1; }
    size_t rd = fread(json, 1, (size_t)fsize, f);
    json[rd] = '\0';
    fclose(f);

    /* Parse nodes */
    int num_nodes = 0, cap_nodes = 256;
    char **node_names = malloc(sizeof(char *) * (size_t)cap_nodes);

    char *p = strstr(json, "\"nodes\"");
    p = strchr(p, '[');
    p++;
    while (*p && *p != ']') {
        if (*p == '"') {
            p++;
            char *start = p;
            while (*p && *p != '"') p++;
            int len = (int)(p - start);
            char *name = malloc((size_t)len + 1);
            memcpy(name, start, (size_t)len);
            name[len] = '\0';
            if (num_nodes == cap_nodes) {
                cap_nodes *= 2;
                node_names = realloc(node_names, sizeof(char *) * (size_t)cap_nodes);
            }
            node_names[num_nodes++] = name;
            p++;
        } else {
            p++;
        }
    }

    /* Parse edges */
    int num_edges = 0, cap_edges = 1024;
    Edge *edges = malloc(sizeof(Edge) * (size_t)cap_edges);

    p = strstr(json, "\"edges\"");
    p = strchr(p, '[');
    p++;
    while (*p && *p != ']') {
        if (*p == '{') {
            char *obj_start = p;
            char *obj_end = strchr(p, '}');
            if (!obj_end) break;

            /* from */
            char *fp = strstr(obj_start, "\"from\"");
            fp = strchr(fp, ':');
            fp = strchr(fp, '"');
            fp++;
            char *fstart = fp;
            while (*fp && *fp != '"') fp++;
            int flen = (int)(fp - fstart);
            char *from_str = malloc((size_t)flen + 1);
            memcpy(from_str, fstart, (size_t)flen);
            from_str[flen] = '\0';

            /* to */
            char *tp = strstr(obj_start, "\"to\"");
            tp = strchr(tp, ':');
            tp = strchr(tp, '"');
            tp++;
            char *tstart = tp;
            while (*tp && *tp != '"') tp++;
            int tlen = (int)(tp - tstart);
            char *to_str = malloc((size_t)tlen + 1);
            memcpy(to_str, tstart, (size_t)tlen);
            to_str[tlen] = '\0';

            /* weight */
            char *wp = strstr(obj_start, "\"weight\"");
            wp = strchr(wp, ':');
            double weight = atof(wp);

            if (num_edges == cap_edges) {
                cap_edges *= 2;
                edges = realloc(edges, sizeof(Edge) * (size_t)cap_edges);
            }

            int from_idx = -1, to_idx = -1;
            for (int i = 0; i < num_nodes; i++) {
                if (strcmp(node_names[i], from_str) == 0) from_idx = i;
                if (strcmp(node_names[i], to_str) == 0) to_idx = i;
            }

            edges[num_edges].from = from_idx;
            edges[num_edges].to = to_idx;
            edges[num_edges].weight = weight;
            num_edges++;

            free(from_str);
            free(to_str);
            p = obj_end + 1;
        } else {
            p++;
        }
    }

    /* Build adjacency list (undirected) */
    int *adj_head = malloc(sizeof(int) * (size_t)num_nodes);
    for (int i = 0; i < num_nodes; i++) adj_head[i] = -1;

    int total_adj = num_edges * 2;
    int *adj_to = malloc(sizeof(int) * (size_t)total_adj);
    double *adj_w = malloc(sizeof(double) * (size_t)total_adj);
    int *adj_next = malloc(sizeof(int) * (size_t)total_adj);
    int adj_count = 0;

    for (int i = 0; i < num_edges; i++) {
        adj_to[adj_count] = edges[i].to;
        adj_w[adj_count] = edges[i].weight;
        adj_next[adj_count] = adj_head[edges[i].from];
        adj_head[edges[i].from] = adj_count++;

        adj_to[adj_count] = edges[i].from;
        adj_w[adj_count] = edges[i].weight;
        adj_next[adj_count] = adj_head[edges[i].to];
        adj_head[edges[i].to] = adj_count++;
    }

    /* Dijkstra */
    double *dist = malloc(sizeof(double) * (size_t)num_nodes);
    int *visited = malloc(sizeof(int) * (size_t)num_nodes);
    for (int i = 0; i < num_nodes; i++) {
        dist[i] = INFINITY;
        visited[i] = 0;
    }

    int src = -1;
    for (int i = 0; i < num_nodes; i++) {
        if (strcmp(node_names[i], "A") == 0) { src = i; break; }
    }
    dist[src] = 0.0;

    for (int iter = 0; iter < num_nodes; iter++) {
        int u = -1;
        double min_d = INFINITY;
        for (int i = 0; i < num_nodes; i++) {
            if (!visited[i] && dist[i] < min_d) {
                min_d = dist[i];
                u = i;
            }
        }
        if (u == -1) break;
        visited[u] = 1;

        for (int e = adj_head[u]; e != -1; e = adj_next[e]) {
            int v = adj_to[e];
            if (!visited[v] && dist[u] + adj_w[e] < dist[v]) {
                dist[v] = dist[u] + adj_w[e];
            }
        }
    }

    /* Sort node indices alphabetically */
    int *order = malloc(sizeof(int) * (size_t)num_nodes);
    for (int i = 0; i < num_nodes; i++) order[i] = i;

    /* Simple insertion sort using strcmp on node names */
    for (int i = 1; i < num_nodes; i++) {
        int key = order[i];
        int j = i - 1;
        while (j >= 0 && strcmp(node_names[order[j]], node_names[key]) > 0) {
            order[j + 1] = order[j];
            j--;
        }
        order[j + 1] = key;
    }

    /* Output */
    printf("=== Shortest Paths from A ===\n");
    printf("\n");
    for (int i = 0; i < num_nodes; i++) {
        int idx = order[i];
        if (isinf(dist[idx])) {
            printf("A -> %s: unreachable\n", node_names[idx]);
        } else if (dist[idx] == (double)(long long)dist[idx]) {
            printf("A -> %s: %lld\n", node_names[idx], (long long)dist[idx]);
        } else {
            printf("A -> %s: %g\n", node_names[idx], dist[idx]);
        }
    }

    /* Cleanup */
    for (int i = 0; i < num_nodes; i++) free(node_names[i]);
    free(node_names);
    free(edges);
    free(adj_head);
    free(adj_to);
    free(adj_w);
    free(adj_next);
    free(dist);
    free(visited);
    free(order);
    free(json);

    return 0;
