func multiply(_ m1: [[Int]], _ m2: [[Int]]) -> [[Int]] {
    let n = m1.count
    let p = m2[0].count
    let m = m2.count
    var result = [[Int]](repeating: [Int](repeating: 0, count: p), count: n)
    for i in 0..<n {
        for j in 0..<p {
            var sum = 0
            for k in 0..<m {
                sum += m1[i][k] * m2[k][j]
            }
            result[i][j] = sum
        }
    }
    return result
