func determinant(_ m: [[Int]]) -> Int {
    let n = m.count
    if n == 1 { return m[0][0] }
    if n == 2 { return m[0][0] * m[1][1] - m[0][1] * m[1][0] }
    var det = 0
    for j in 0..<n {
