func multiply(_ m1: [[Int]], _ m2: [[Int]]) -> [[Int]] {
    let n = m1.count
    let p = m2[0].count
    let m = m2.count
    var result = [[Int]](repeating: [Int](repeating: 0, count: p), count: n)
    for i in 0..<n {
        for j in 0..<p {
            var sum = 0
            for k in 0..<m {
                sum += m1[i][k] * m2[k][j]
            }
            result[i][j] = sum
        }
    }
    return result
}

func determinant(_ m: [[Int]]) -> Int {
    let n = m.count
    if n == 1 { return m[0][0] }
    if n == 2 { return m[0][0] * m[1][1] - m[0][1] * m[1][0] }
    var det = 0
    for j in 0..<n {
        var minor = [[Int]]()
        for i in 1..<n {
            var row = [Int]()
            for k in 0..<n where k != j {
                row.append(m[i][k])
            }
            minor.append(row)
        }
        det += (j % 2 == 0 ? 1 : -1) * m[0][j] * determinant(minor)
    }
    return det
}

