#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>

typedef struct {
    char *name;
    int count;
} NameCount;

typedef struct {
    NameCount *items;
    int count;
    int capacity;
} NameCountList;

NameCountList *ncl_new(int cap) {
    NameCountList *n = (NameCountList *)malloc(sizeof(NameCountList));
    n->items = (NameCount *)malloc(cap * sizeof(NameCount));
    n->count = 0;
    n->capacity = cap;
    return n;
}

int ncl_find(NameCountList *n, const char *name) {
    for (int i = 0; i < n->count; i++) {
        if (strcmp(n->items[i].name, name) == 0) return i;
    }
    return -1;
}

void ncl_add(NameCountList *n, const char *name) {
    int idx = ncl_find(n, name);
    if (idx >= 0) {
        n->items[idx].count++;
    } else {
        if (n->count >= n->capacity) {
            n->capacity *= 2;
            n->items = (NameCount *)realloc(n->items, n->capacity * sizeof(NameCount));
        }
        n->items[n->count].name = strdup(name);
        n->items[n->count].count = 1;
        n->count++;
    }
}

typedef struct {
    char **items;
    int count;
    int capacity;
} StrList;

StrList *sl_new(int cap) {
    StrList *s = (StrList *)malloc(sizeof(StrList));
    s->items = (char **)malloc(cap * sizeof(char *));
    s->count = 0;
    s->capacity = cap;
    return s;
}

void sl_add(StrList *s, const char *str) {
    if (s->count >= s->capacity) {
        s->capacity *= 2;
        s->items = (char **)realloc(s->items, s->capacity * sizeof(char *));
    }
    s->items[s->count] = strdup(str);
    s->count++;
}

int sl_contains(StrList *s, const char *str) {
    for (int i = 0; i < s->count; i++) {
        if (strcmp(s->items[i], str) == 0) return 1;
    }
    return 0;
}

int cmp_str(const void *a, const void *b) {
    return strcmp(*(const char **)a, *(const char **)b);
}

int cmp_namecount(const void *a, const void *b) {
    return strcmp(((const NameCount *)a)->name, ((const NameCount *)b)->name);
}

int main(void) {
    const char *filepath = "<tmp>";
    FILE *f = fopen(filepath, "r");
    if (!f) {
        fprintf(stderr, "Cannot open file\n");
        return 1;
    }

    NameCountList *levels = ncl_new(8);
    NameCountList *comp_errors = ncl_new(16);
    StrList *err_msgs = sl_new(64);
    int hour_counts[24] = {0};

    char *line = NULL;
    size_t linecap = 0;
    ssize_t len;

    while ((len = getline(&line, &linecap, f)) != -1) {
        while (len > 0 && (line[len - 1] == '\n' || line[len - 1] == '\r'))
            line[--len] = '\0';
        if (len == 0) continue;

        char *close_bracket = strchr(line, ']');
        if (!close_bracket) continue;

        int hour = 0;
        if (len >= 14) {
            hour = (line[12] - '0') * 10 + (line[13] - '0');
        }
        if (hour >= 0 && hour < 24) hour_counts[hour]++;

        char *p = close_bracket + 1;
        if (*p == ' ') p++;

        char *level_start = p;
        while (*p && *p != ' ') p++;
        char level_end = *p;
        *p = '\0';
        char *level = level_start;

        ncl_add(levels, level);

        *p = level_end;
        p++;

        if (*p == ' ' && p[1] == '(') p += 2;
        else if (*p == '(') p++;

        char *comp_start = p;
        while (*p && *p != ')') p++;
        char comp_end = *p;
        *p = '\0';
        char *component = comp_start;

        if (strcmp(level, "ERROR") == 0) {
            ncl_add(comp_errors, component);

            *p = comp_end;
            p++;
            if (*p == ' ') p++;
            if (*p == '-' && p[1] == ' ') p += 2;

            if (!sl_contains(err_msgs, p)) {
                sl_add(err_msgs, p);
            }
        }
    }

    fclose(f);
    free(line);

    qsort(levels->items, levels->count, sizeof(NameCount), cmp_namecount);
    qsort(err_msgs->items, err_msgs->count, sizeof(char *), cmp_str);

    int best_comp = 0;
    for (int i = 1; i < comp_errors->count; i++) {
        if (comp_errors->items[i].count > comp_errors->items[best_comp].count) {
            best_comp = i;
        }
    }

    int best_hour = 0;
    for (int i = 1; i < 24; i++) {
        if (hour_counts[i] > hour_counts[best_hour]) {
            best_hour = i;
        }
    }

    printf("=== Log Analysis ===\n");
    printf("\n");
    printf("Entries by Level:\n");
    for (int i = 0; i < levels->count; i++) {
        printf("  %s: %d\n", levels->items[i].name, levels->items[i].count);
    }
    printf("\n");
    if (comp_errors->count > 0) {
        printf("Component with Most Errors: %s (%d errors)\n",
               comp_errors->items[best_comp].name, comp_errors->items[best_comp].count);
    }
    printf("\n");
    printf("Unique Error Messages:\n");
    for (int i = 0; i < err_msgs->count; i++) {
        printf("  - %s\n", err_msgs->items[i]);
    }
    printf("\n");
    printf("Busiest Hour: %02d:00 (%d entries)\n", best_hour, hour_counts[best_hour]);

    return 0;
}

